/* Generated by npm run build:pwa. Cache only the verified public shell, never API/user data. */
const REVISION = "__REVISION__";
const SHELL = __SHELL__;
const BASE = new URL(self.registration.scope);
const PREFIX = "nutriai-shell:" + BASE.pathname + ":";
const CACHE = PREFIX + REVISION;
const allowed = new Set(SHELL.map(asset => new URL(asset.url, BASE).href));
const indexURL = new URL("index.html", BASE).href;

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    try {
      const cache = await caches.open(CACHE);
      await Promise.all(SHELL.map(async asset => {
        const url = new URL(asset.url, BASE);
        const response = await fetch(new Request(url, { cache: "reload", credentials: "omit" }));
        if (!response.ok || response.redirected || response.type === "opaque") throw new Error("Invalid shell response");
        const bytes = await response.clone().arrayBuffer();
        const digest = await crypto.subtle.digest("SHA-256", bytes);
        const hash = Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, "0")).join("");
        if (hash !== asset.sha256) throw new Error("Shell integrity mismatch: " + asset.url);
        await cache.put(url, response);
      }));
    } catch (error) {
      await caches.delete(CACHE);
      throw error; // An incomplete deployment never replaces the working offline shell.
    }
    // No skipWaiting here: updates must not interrupt a camera session or a form.
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith(PREFIX) && key !== CACHE).map(key => caches.delete(key)));
    // No clients.claim(): leave currently open, uncontrolled documents untouched.
  })());
});

self.addEventListener("message", event => {
  if (event.data?.type !== "ACTIVATE_UPDATE") return;
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    const ownWindows = windows.filter(client => client.url.startsWith(BASE.href));
    if (ownWindows.length > 1) {
      event.source?.postMessage({ type: "UPDATE_BLOCKED" });
      return;
    }
    await self.skipWaiting();
  })());
});

self.addEventListener("fetch", event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== BASE.origin || request.headers.has("authorization")) return;
  // Exact URL allowlist also excludes /api/*, user photos, query strings and all external CDNs.
  const home = request.mode === "navigate" && !url.search && (url.href === BASE.href || url.href === indexURL);
  if (!home && !allowed.has(url.href)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(home ? indexURL : request);
    if (cached) return cached;
    // No runtime cache writes: even an unexpected response cannot become a stored shell asset.
    return fetch(request);
  })());
});
